// File: src/domain/order/Order.ts
import { SqlOrderRepository } from '../../infrastructure/db/SqlOrderRepository';

export class Order {
  save() {
    const repo = new SqlOrderRepository();
    repo.persist(this);
  }
}

// Service Layer
class PaymentService {
  pay(orderId: string, amount: number) {
    const order = repo.findById(orderId);
    if (order.status !== 'PENDING') throw new Error('Invalid status');
    if (amount <= 0) throw new Error('Invalid amount');

    order.paidAmount += amount;
    order.status = 'PAID';
    repo.save(order);
  }
}

// Domain Layer
class Order {
  public status: string;
  public paidAmount: number;
}

// Controller Layer
@Get('/users/:id')
async getUser(@Param('id') id: string) {
  const userEntity = await this.repo.findOne(id); // Returns ORM Entity
  return userEntity;
}

